-- Chinese Radiance Nexus Night Lulu alternate art. Safe to run more than once.
insert into promo_items (id, r, data)
select 'item-10781', 10781, $j${"cat": "PROMO", "nm": "Akali - Brash (City Challenge S5 Champion)", "se": "RAD", "cn": "015", "ra": "Promo", "do": "Fury", "tg": "Akali\nCity Challenge\nChampion reward card", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/akali-brash-city-challenge-s5-champion-ch-item-10781.webp", "inf": "City Challenge Season 5 promo with the promo stamp (RAD 015, Simplified Chinese). Stage 1 (Oct 31 to Dec 6) champion reward.", "r": 10781, "id": "item-10781", "la": "Chinese", "ev": "CC - China", "ty": "Card", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": ""}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10781' or (data->>'nm' = $n$Akali - Brash (City Challenge S5 Champion)$n$ and data->>'la' = 'Chinese'));
