insert into promo_items (id, r, data)
select 'item-10789', 10789, (e.data - 'st' - 'tp' - 'tn_name') || jsonb_build_object('r', 10789, 'id', 'item-10789', 'la', 'Chinese', 'ev', 'NN - China', 'img', 'https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/lulu-whimsical-radiance-nexus-night-ch-item-10789.webp', 'inf', 'Chinese Radiance Nexus Night alternate-art Lulu (promo stamp, Simplified Chinese). Random chance in the Radiance Nexus Night event pack, from Oct 30, 2026.') || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
from (select data from promo_items where data->>'nm' = $n$Lulu - Whimsical (Radiance Nexus Night)$n$ and data->>'la' = 'English' limit 1) e
where not exists (select 1 from promo_items where id = 'item-10789' or (data->>'nm' = $n$Lulu - Whimsical (Radiance Nexus Night)$n$ and data->>'la' = 'Chinese'));
update promo_items set data = data || jsonb_build_object('img', 'https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/lulu-whimsical-radiance-nexus-night-ch-item-10789.webp')
 where data->>'nm' = $n$Lulu - Whimsical (Radiance Nexus Night)$n$ and data->>'la' = 'Chinese' and coalesce(data->>'img','') = '';
-- Fallback if there was no English row to copy from.
